# ============================ 内置默认字典 ================================= #
# ⚠️ 把 YOUR_BASE64_STRING_HERE 替换成你生成的 Base64 字符串
DEFAULT_DICT_ENCODED = ""

_default_words = None

def get_default_dict() -> List[bytes]:
    """解压内置默认字典，返回去重后的 bytes 密码列表。"""
    global _default_words
    if _default_words is not None:
        return _default_words[:]
    _default_words = []
    try:
        decoded = base64.b64decode(DEFAULT_DICT_ENCODED)
        text = zlib.decompress(decoded).decode("utf-8")
        seen = set()
        for line in text.splitlines():
            word = line.strip().encode("utf-8")
            if word and word not in seen:
                seen.add(word)
                _default_words.append(word)
    except Exception as e:
        print(f"⚠️ 默认字典加载失败：{e}")
    return _default_words[:]



class ETASmoother:
    """滑动窗口 + 去掉异常值 + 平均速度 的剩余时间平滑器"""
    def __init__(self, window_seconds=3.0, sample_interval=0.3):
        self.window_seconds = window_seconds
        self.sample_interval = sample_interval
        self.points = []                # [(时间戳, 完成比例0~1), ...]
        self._last_sample = 0
    def add(self, progress):
        now = time.time()
        # 控制采样频率，避免点数过多
        if now - self._last_sample < self.sample_interval:
            return None
        self._last_sample = now
        self.points.append((now, progress))
        # 只保留最近 window_seconds 秒的数据
        self.points = [(t, p) for t, p in self.points if now - t <= self.window_seconds]
        if len(self.points) < 2:
            return None
        # 计算滑动窗口内每两个采集点之间的速度（比例/秒）
        speeds = []
        for i in range(1, len(self.points)):
            dt = self.points[i][0] - self.points[i - 1][0]
            dp = self.points[i][1] - self.points[i - 1][1]
            if dt > 0:
                speeds.append(dp / dt)
        if not speeds:
            return None
        # 去掉异常值：与中位数偏差超过 50% 的速度点剔除
        med = statistics.median(speeds)
        filtered = [s for s in speeds if abs(s - med) <= med * 0.5 + 1e-9]
        if not filtered:
            filtered = speeds
        avg_speed = sum(filtered) / len(filtered)
        if avg_speed <= 1e-9:
            return None
        remaining = (1.0 - progress) / avg_speed
        return remaining



# ============================ 高 DPI 适配 ================================= #
def setup_dpi() -> float:
    """启用进程级 DPI 感知并返回缩放系数（必须在创建 Tk 窗口之前调用）。"""
    if os.name != "nt":
        return 1.0
    try:
        import ctypes
        try:
            ctypes.windll.shcore.SetProcessDpiAwareness(2)
        except Exception:
            ctypes.windll.user32.SetProcessDPIAware()
        dpi = ctypes.windll.user32.GetDpiForSystem()
        return dpi / 96.0
    except Exception:
        return 1.0

DPI_SCALE = setup_dpi()

def S(v: float) -> int:
    """把固定像素尺寸按 DPI 比例放大。"""
    return int(round(v * DPI_SCALE))

def setup_window_scaling(root: tk.Tk) -> None:
    """设置 Tk 文本缩放，使 pt 字号随 DPI 自动放大。"""
    if DPI_SCALE != 1.0:
        try:
            root.tk.call("tk", "scaling", 96 * DPI_SCALE / 72.0)
        except Exception:
            pass

# ============================ 数据存储（合并为一个 json）================= #
def get_app_dir() -> Path:
    if getattr(sys, 'frozen', False):
        return Path(sys.executable).parent
    return Path(__file__).resolve().parent

APP_DIR = get_app_dir()
DATA_FILE = APP_DIR / "app_data.json"         # 唯一数据文件

# 旧的独立文件（仅用于首次自动迁移）
OLD_CONFIG_FILE = APP_DIR / "config.json"
OLD_HISTORY_FILE = APP_DIR / "history.json"
OLD_BREAKPOINT_FILE = APP_DIR / "breakpoint.json"

def _read_json(path: Path) -> any:
    try:
        with open(path, "r", encoding="utf-8") as f:
            return json.load(f)
    except Exception:
        return None

def _write_json(path: Path, data: any) -> None:
    tmp = path.with_suffix(".tmp")
    try:
        with open(tmp, "w", encoding="utf-8") as f:
            json.dump(data, f, ensure_ascii=False, indent=2)
        os.replace(tmp, path)
    except Exception:
        pass

def load_app_data() -> dict:
    """读取唯一数据文件；如果不存在，则尝试从旧 json 迁移。"""
    data = _read_json(DATA_FILE)
    if data is not None and isinstance(data, dict):
        data.setdefault("config", {})
        data.setdefault("history", [])
        data.setdefault("breakpoint", None)
        return data

    # 首次运行：尝试合并旧文件
    old_config = _read_json(OLD_CONFIG_FILE)
    old_history = _read_json(OLD_HISTORY_FILE)
    old_bp = _read_json(OLD_BREAKPOINT_FILE)
    data = {
        "config": old_config if isinstance(old_config, dict) else {},
        "history": old_history if isinstance(old_history, list) else [],
        "breakpoint": old_bp if isinstance(old_bp, dict) else None,
    }
    _write_json(DATA_FILE, data)
    return data

def save_app_data(data: dict) -> None:
    _write_json(DATA_FILE, data)

# --- config 包装 --- #
def load_config() -> dict:
    return load_app_data().get("config", {})

def save_config(cfg: dict) -> None:
    data = load_app_data()
    data["config"] = cfg
    save_app_data(data)

# --- history 包装 --- #
def load_history() -> list:
    return load_app_data().get("history", [])

def save_history(history: list) -> None:
    data = load_app_data()
    data["history"] = history
    save_app_data(data)

# --- breakpoint 包装 --- #
def load_breakpoint() -> Optional[dict]:
    return load_app_data().get("breakpoint")

def save_breakpoint(bp: dict) -> None:
    data = load_app_data()
    data["breakpoint"] = bp
    save_app_data(data)

def clear_breakpoint() -> None:
    data = load_app_data()
    data["breakpoint"] = None
    save_app_data(data)

# ============================ 字典工具 ===================================== #
def load_passwords_from_file(path: str) -> List[bytes]:
    """从文件读取字典 -> bytes 列表。"""
    out = []
    with open(path, "rb") as f:
        for raw in f:
            line = raw[:-1] if raw.endswith(b"\n") else raw
            if line.endswith(b"\r"):
                line = line[:-1]
            if line:
                out.append(line)
    return out

def ensure_builtin_file(words: List[bytes]) -> Path:
    """确保内置字典临时文件存在（用于 7z 多进程调用）。"""
    need = True
    if BUILTIN_DICT_FILE.exists():
        try:
            if len(load_passwords_from_file(str(BUILTIN_DICT_FILE))) == len(words):
                need = False
        except Exception:
            need = True
    if need:
        with open(BUILTIN_DICT_FILE, "wb") as f:
            for w in words:
                f.write(w + b"\n")
    return BUILTIN_DICT_FILE

BUILTIN_DICT_FILE = APP_DIR / "builtin_dict.txt"

# ============================ 字典对象 ===================================== #
class DictEntry:
    """字典条目：可以是内置默认字典，也可以是外部字典文件。"""
    def __init__(self, name: str, path: Optional[str] = None, is_builtin: bool = False):
        self.name = name
        self.path = path
        self.is_builtin = is_builtin
        self.words: List[bytes] = []
        self.word_count = 0
        self._loaded = False

    def load(self) -> List[bytes]:
        if not self._loaded:
            if self.is_builtin:
                self.words = get_default_dict()
            else:
                self.words = load_passwords_from_file(self.path)
            self.word_count = len(self.words)
            self._loaded = True
        return self.words

    def __repr__(self):
        return f"<DictEntry {self.name} ({self.word_count})>"

# ============================ 窗口图标 ===================================== #
def create_icon() -> tk.PhotoImage:
    """生成一个 64x64 的锁形图标。"""
    try:
        from PIL import Image, ImageDraw
        img = Image.new("RGBA", (64, 64), (0, 0, 0, 0))
        d = ImageDraw.Draw(img)
        d.rounded_rectangle([2, 2, 61, 61], radius=16, fill="#89b4fa")
        d.rounded_rectangle([24, 14, 39, 28], radius=6, fill="#1e1e2e")
        d.rounded_rectangle([16, 24, 47, 47], radius=10, fill="#1e1e2e")
        d.ellipse([26, 33, 37, 44], fill="#f9e2af")
        import io, tempfile
        buf = io.BytesIO()
        img.save(buf, format="PNG")
        tmp = os.path.join(tempfile.gettempdir(), "recovery_icon.png")
        with open(tmp, "wb") as f:
            f.write(buf.getvalue())
        return tk.PhotoImage(file=tmp)
    except Exception:
        img = tk.PhotoImage(width=64, height=64)
        img.put("#89b4fa", to=(2, 2, 61, 61))
        img.put("#1e1e2e", to=(24, 14, 39, 28))
        img.put("#1e1e2e", to=(16, 24, 47, 47))
        img.put("#f9e2af", to=(26, 33, 37, 44))
        img.put("#ffffff", to=(0, 0, 63, 1))
        img.put("#ffffff", to=(0, 0, 1, 63))
        img.put("#ffffff", to=(63, 0, 64, 63))
        img.put("#ffffff", to=(0, 63, 63, 64))
        img.configure(transparentcolor="#ffffff")
        return img

def set_window_icon(root: tk.Tk) -> None:
    try:
        icon = create_icon()
        root.iconphoto(True, icon)
        root._icon_img = icon
    except Exception:
        pass

# ============================ 剪贴板（修复版）============================= #
def copy_to_clipboard(root, text: str) -> bool:
    """
    复制文本到剪贴板。
    首选 Tk 原生剪贴板（最可靠），失败时回退到 Windows ctypes API。
    """
    # 方法一：Tk 原生剪贴板
    try:
        root.clipboard_clear()
        root.clipboard_append(text)
        root.update()
        return True
    except Exception:
        pass

    # 方法二：Windows 原生 API（兜底）
    if sys.platform == "win32":
        try:
            import ctypes
            k = ctypes.windll.kernel32
            u = ctypes.windll.user32
            bdata = (text + "\0").encode("utf-16-le")
            h = k.GlobalAlloc(0x0002, len(bdata))
            if not h:
                return False
            ptr = k.GlobalLock(h)
            if not ptr:
                return False
            ctypes.memmove(ptr, bdata, len(bdata))
            k.GlobalUnlock(h)
            if not u.OpenClipboard(0):
                return False
            u.EmptyClipboard()
            u.SetClipboardData(13, h)
            u.CloseClipboard()
            return True
        except Exception:
            return False
    return False

# ============================ 7z 工具 ===================================== #
def find_7z() -> Optional[str]:
    from shutil import which
    for name in ("7z", "7z.exe", "7za", "7za.exe", "7zr", "7zr.exe"):
        p = which(name)
        if p:
            return p
    cands = [
        r"C:\Program Files\7-Zip\7z.exe",
        r"C:\Program Files (x86)\7-Zip\7z.exe",
        str(Path(os.environ.get("ProgramFiles", "")) / "7-Zip" / "7z.exe"),
        str(Path(os.environ.get("ProgramFiles(x86)", "")) / "7-Zip" / "7z.exe"),
    ]
    for c in cands:
        if c and os.path.isfile(c):
            return c
    return None


DETACHED_PROCESS = 0x00000008

def test_7z_password(sevenzip: str, archive: str, pw_bytes: bytes) -> bool:
    try:
        pw = pw_bytes.decode("utf-8", "surrogateescape")
    except Exception:
        pw = pw_bytes.decode("latin-1", "replace")
    try:
        r = subprocess.run([sevenzip, "t", archive, "-p" + pw, "-y"],
                           stdin=subprocess.DEVNULL,
                           stdout=subprocess.DEVNULL,
                           stderr=subprocess.DEVNULL,
                           creationflags=DETACHED_PROCESS)        
        return r.returncode == 0
    except Exception:
        return False

def is_aes_zip(path: str) -> bool:
    try:
        with zipfile.ZipFile(path) as zf:
            for zi in zf.infolist():
                if (zi.flag_bits & 0x1) and zi.compress_type == 99:
                    return True
    except Exception:
        pass
    return False

# ============================ 多进程 7z worker ============================ #
def _7z_proc_entry(archive: str, dict_path: str, sevenzip: str,
                   counter, found, found_pw, current, start_index: int,
                   stop_event) -> None:
    words = load_passwords_from_file(dict_path)
    n = len(words)
    while not stop_event.is_set():
        with counter.get_lock():
            if found.value or counter.value >= n:
                return
            idx = counter.value
            counter.value += 1
        if idx < start_index:
            continue
        pw = words[idx]
        try:
            current[:60] = pw[:60].ljust(60, b" ")
        except Exception:
            pass
        if test_7z_password(sevenzip, archive, pw):
            found.value = 1
            try:
                found_pw.value = pw[:255]
            except Exception:
                pass
            return

# ============================ ZIP 多线程 ================================== #
def crack_zip_thread(archive_path: str, passwords: List[bytes],
                     start_index: int, shared: dict, stop_flag) -> Tuple[str, Optional[bytes]]:
    total = len(passwords)
    if start_index >= total:
        return ("fail", None)
    try:
        zf = zipfile.ZipFile(archive_path)
    except Exception as e:
        return ("error", str(e).encode())

    enc = [zi for zi in zf.infolist() if zi.flag_bits & 0x1]
    if not enc:
        zf.close()
        return ("noenc", None)
    if any(zi.compress_type == 99 for zi in enc):
        zf.close()
        return ("aes", None)
    member_name = min(enc, key=lambda z: z.file_size).filename
    zf.close()

    counter = [start_index]
    found = [False]
    found_pw = [None]
    current = [b""]
    shared["counter"] = counter
    shared["found"] = found
    shared["pw"] = found_pw
    shared["current"] = current

    lock = threading.Lock()
    num_threads = max(1, os.cpu_count() or 2)

    def worker():
        z = zipfile.ZipFile(archive_path)
        m = z.getinfo(member_name)
        try:
            while True:
                if stop_flag.is_set() or found[0]:
                    return
                with lock:
                    if counter[0] >= total:
                        return
                    idx = counter[0]
                    counter[0] += 1
                if idx < start_index:
                    continue
                pw = passwords[idx]
                current[0] = pw
                try:
                    with z.open(m, pwd=pw) as fp:
                        while fp.read(1 << 16):
                            pass
                except (RuntimeError, zipfile.BadZipFile, OSError,
                        zlib.error, NotImplementedError):
                    continue
                else:
                    found[0] = True
                    found_pw[0] = pw
                    return
        finally:
            z.close()

    threads = [threading.Thread(target=worker, daemon=True) for _ in range(num_threads)]
    for t in threads:
        t.start()

    while not stop_flag.is_set():
        if found[0] or counter[0] >= total:
            break
        time.sleep(0.05)

    if found[0]:
        stop_flag.set()
        for t in threads:
            t.join(timeout=2)
        return ("found", found_pw[0])

    # 被手动停止
    if stop_flag.is_set() and counter[0] < total:
        stop_flag.set()
        for t in threads:
            t.join(timeout=2)
        return ("stopped", None)

    # 正常跑完
    stop_flag.set()
    for t in threads:
        t.join(timeout=2)
    return ("fail", None)

# ============================ 7z 多进程 =================================== #
def crack_7z_process(archive: str, dict_path: str, sevenzip: str,
                     total: int, start_index: int, shared: dict, stop_flag) -> Tuple[str, Optional[bytes]]:
    if total == 0:
        return ("empty", None)
    if start_index >= total:
        return ("fail", None)
    if test_7z_password(sevenzip, archive, b"___z__nopass__"):
        return ("noenc", None)

    counter = mp.Value("Q", start_index)
    found = mp.Value("b", 0)
    found_pw = mp.Array("c", 256)
    current = mp.Array("c", 64)
    stop_event = mp.Event()          # 新增：子进程停止信号
    shared["counter"] = counter
    shared["found"] = found
    shared["pw"] = found_pw
    shared["current"] = current

    num_procs = max(1, os.cpu_count() or 2)
    procs = [
        mp.Process(target=_7z_proc_entry,
                   args=(archive, dict_path, sevenzip, counter, found,
                         found_pw, current, start_index, stop_event),
                   daemon=True)
        for _ in range(num_procs)
    ]
    for p in procs:
        p.start()

    while not stop_flag.is_set():
        if found.value or counter.value >= total:
            break
        time.sleep(0.05)

    stop_event.set()  # 通知所有子进程立即退出

    if found.value:
        with counter.get_lock():
            counter.value = total + 1
        for p in procs:
            p.join(timeout=5)
            if p.is_alive():
                p.terminate()
        return ("found", bytes(found_pw.value))

    # 被手动停止
    if stop_flag.is_set() and counter.value < total:
        for p in procs:
            p.join(timeout=2)
            if p.is_alive():
                p.terminate()
        return ("stopped", None)

    # 正常跑完
    with counter.get_lock():
        counter.value = total + 1
    for p in procs:
        p.join(timeout=5)
        if p.is_alive():
            p.terminate()
    return ("fail", None)

# ============================ 主界面 ====================================== #
class App:
    def __init__(self, master: tk.Tk):
        self.master = master
        self.cfg = load_config()
        self.dict_library: List[DictEntry] = []
        self.active_dicts: List[int] = []
        self.archive = ""
        self.shared: dict = {}
        self.stop_flag = threading.Event()
        self.worker_thread: Optional[threading.Thread] = None
        self.running = False

        self._last_check_time = time.time()
        self._last_check_count = 0
        self._speed = 0.0
        self._eta = "--"
        self._work_words: List[bytes] = []
        self._temp_dict_file: Optional[str] = None
        self._crack_start_time: float = 0.0
        self._eta_smoother = ETASmoother(window_seconds=3.0)
        self._dm_win = None
        self._history_detail = None

        # 断点续破相关
        self._resume_from = 0
        self._progress_count = 0
        self._shuffle_seed = None

        master.title(f"🔐 密码字典恢复工具 v{VERSION}")
        master.geometry(f"{S(800)}x{S(700)}")
        master.minsize(S(760), S(640))
        master.configure(bg="#1e1e2e")

        self.style = ttk.Style(master)
        try:
            self.style.theme_use("clam")
        except Exception:
            pass

        self._build_ui()
        self._load_dict_library()

        # 窗口关闭事件（保存断点）
        master.protocol("WM_DELETE_WINDOW", self._on_close)

    # ---------------- 界面构建 ---------------- #
    def _build_ui(self):
        title = tk.Label(self.master, text="🔐 密码字典恢复工具",
                         font=("Microsoft YaHei", 22, "bold"),
                         bg="#1e1e2e", fg="#89b4fa")
