        sub = tk.Label(self.master, text="ZIP / 7z / RAR  ·  多字典组合  ·  实时速度",
                       font=("Microsoft YaHei", 10),
                       bg="#1e1e2e", fg="#a6adc8")
        sub.pack(pady=(0, S(12)))

        main = tk.Frame(self.master, bg="#1e1e2e")
        main.pack(fill=tk.BOTH, expand=True, padx=S(20), pady=S(10))

        # ---- 压缩包区 ----
        self._card_archive = self._make_card(main, "📦 目标压缩包")
        self._card_archive.pack(fill=tk.X, pady=S(5))
        self.btn_pick = tk.Button(self._card_archive, text="选择压缩包",
                                  command=self.select_archive,
                                  font=("Microsoft YaHei", 10),
                                  bg="#89b4fa", fg="#11111b",
                                  activebackground="#74c7ec",
                                  relief="flat", cursor="hand2")
        self.btn_pick.pack(side=tk.LEFT, padx=S(5), pady=S(5))
        self.entry_archive = tk.Entry(self._card_archive, font=("Consolas", 9),
                                      bg="#181825", fg="#cdd6f4",
                                      insertbackground="#cdd6f4")
        self.entry_archive.pack(side=tk.LEFT, fill=tk.X, expand=True,
                                padx=S(5), pady=S(5))

