    def _make_card(self, parent, title):
        card = tk.Frame(parent, bg="#2a2a3e", bd=1, relief="groove")
        lbl = tk.Label(card, text=title, font=("Microsoft YaHei", 11, "bold"),
                       bg="#2a2a3e", fg="#89b4fa", anchor="w")
        lbl.pack(fill=tk.X, padx=S(8), pady=(S(6), 0))
        inner = tk.Frame(card, bg="#2a2a3e")
        inner.pack(fill=tk.X, padx=S(5), pady=S(3))
        card._inner = inner
        return card

    # ---------------- 字典库管理 ---------------- #
    def _load_dict_library(self):
        """从配置加载字典库。"""
        cfg = self.cfg
        self.dict_library = []

        # 内置字典始终存在
        builtin_entry = DictEntry("内置默认字典", is_builtin=True)
        builtin_entry.load()
        self.dict_library.append(builtin_entry)

        # 外部字典
        for item in cfg.get("dict_library", []):
            path = item.get("path") if isinstance(item, dict) else item
            if not path or not os.path.isfile(path):
                continue
            name = item.get("name", Path(path).stem) if isinstance(item, dict) else Path(path).stem
            entry = DictEntry(name, path, is_builtin=False)
            entry.load()
            self.dict_library.append(entry)

        # 激活字典
        active_names = cfg.get("active_dicts", [])
        if active_names:
            self.active_dicts = [i for i, e in enumerate(self.dict_library) if e.name in active_names]
        if not self.active_dicts:
            self.active_dicts = list(range(len(self.dict_library)))

        self._update_dict_label()
        self.lbl_status.config(text=f"已加载 {len(self.dict_library)} 个字典，当前启用 {len(self.active_dicts)} 个")

    def _update_dict_label(self):
        """更新主页面显示的当前字典信息。"""
        if not self.dict_library:
            self.lbl_dict.config(text="当前字典：无")
            return
        names = [self.dict_library[i].name for i in self.active_dicts]
        if not names:
            self.lbl_dict.config(text="当前字典：未选择")
            return
        total_words = sum(self.dict_library[i].word_count for i in self.active_dicts)
        text = f"已启用 {len(names)} 个字典：{'、'.join(names)}（共 {total_words} 条）"
        self.lbl_dict.config(text=text)

    def open_dict_manager(self):
        """多字典管理窗口：添加 / 删除 / 勾选 / 复制选中字典。"""
        win = tk.Toplevel(self.master)
        win.title("🗂️ 多字典管理")
        win.geometry(f"{S(700)}x{S(560)}")
        win.configure(bg="#1e1e2e")
        win.transient(self.master)
        win.grab_set()
        self._dm_win = win

        # 工作副本（不直接改动 self.dict_library，直到点击“保存并应用”）
        self._dm_library: List[DictEntry] = [DictEntry(e.name, e.path, e.is_builtin) for e in self.dict_library]
        for entry in self._dm_library:
            entry.load()
        self._dm_vars: List[Tuple[DictEntry, tk.BooleanVar, tk.Label]] = []
        active_names = [self.dict_library[i].name for i in self.active_dicts]
        for entry in self._dm_library:
            var = tk.BooleanVar(value=(entry.name in active_names))
            self._dm_vars.append((entry, var, None))

        # 顶部按钮
        top = tk.Frame(win, bg="#1e1e2e")
        top.pack(fill=tk.X, padx=S(10), pady=(S(10), S(4)))
        tk.Button(top, text="➕ 添加外部字典", command=self._dm_add_external,
                  font=("Microsoft YaHei", 9), bg="#a6e3a1", fg="#11111b",
                  relief="flat", cursor="hand2").pack(side=tk.LEFT, padx=S(4))
        tk.Button(top, text="❌ 移除选中", command=lambda: self._dm_remove_selected(),
                  font=("Microsoft YaHei", 9), bg="#f38ba8", fg="#11111b",
                  relief="flat", cursor="hand2").pack(side=tk.LEFT, padx=S(4))
        self._dm_copy_btn = tk.Button(top, text="📋 复制选中内容", command=self._dm_copy_selected,
                                      font=("Microsoft YaHei", 9), bg="#89dceb", fg="#11111b",
                                      relief="flat", cursor="hand2", state=tk.DISABLED)
        self._dm_copy_btn.pack(side=tk.LEFT, padx=S(4))
        tk.Button(top, text="✅ 全选", command=lambda: self._dm_select_all(True),
                  font=("Microsoft YaHei", 9), bg="#cba6f7", fg="#11111b",
                  relief="flat", cursor="hand2").pack(side=tk.LEFT, padx=S(4))
        tk.Button(top, text="⬜ 全不选", command=lambda: self._dm_select_all(False),
                  font=("Microsoft YaHei", 9), bg="#6c7086", fg="#11111b",
                  relief="flat", cursor="hand2").pack(side=tk.LEFT, padx=S(4))

        # 滚动区
        body = tk.Frame(win, bg="#1e1e2e")
        body.pack(fill=tk.BOTH, expand=True, padx=S(10), pady=S(4))
        canvas = tk.Canvas(body, bg="#1e1e2e", highlightthickness=0)
        sb = tk.Scrollbar(body, orient="vertical", command=canvas.yview)
        canvas.configure(yscrollcommand=sb.set)
        self._dm_frame = tk.Frame(canvas, bg="#1e1e2e")
        self._dm_frame_id = canvas.create_window((0, 0), window=self._dm_frame, anchor="nw")
        self._dm_frame.bind("<Configure>",
                            lambda e: canvas.configure(scrollregion=canvas.bbox("all")))
        canvas.pack(side=tk.LEFT, fill=tk.BOTH, expand=True)
        sb.pack(side=tk.RIGHT, fill=tk.Y)

        # 底部保存
        bottom = tk.Frame(win, bg="#1e1e2e")
        bottom.pack(fill=tk.X, padx=S(10), pady=S(8))
        self._dm_info = tk.Label(bottom, text="", font=("Microsoft YaHei", 9),
                                 bg="#1e1e2e", fg="#a6adc8")
        self._dm_info.pack(side=tk.LEFT)
        tk.Button(bottom, text="💾 保存并应用", command=lambda: self._dm_save(win),
                  font=("Microsoft YaHei", 10, "bold"), bg="#a6e3a1", fg="#11111b",
                  relief="flat", cursor="hand2").pack(side=tk.RIGHT)

        self._dm_render()
        self._dm_update_info()

    def _dm_render(self):
        """重新绘制字典列表，使用大号勾选框。"""
        for w in self._dm_frame.winfo_children():
            w.destroy()

        for i in range(len(self._dm_vars)):
            entry, var, _ = self._dm_vars[i]
            row = tk.Frame(self._dm_frame, bg="#2a2a3e", bd=0)
            row.pack(fill=tk.X, padx=S(4), pady=S(2))

            # 大号复选框 (☐ / ☑)
            check_label = tk.Label(row, text="☐", font=("Segoe UI Symbol", 18, "bold"),
                                   bg="#2a2a3e", fg="#6c7086",
                                   cursor="hand2", width=S(2))
            check_label.pack(side=tk.LEFT, padx=(S(6), S(2)))
            check_label.bind("<Button-1>", lambda e, idx=i: self._dm_toggle(idx))
            row.bind("<Button-1>", lambda e, idx=i: self._dm_toggle(idx))

            name_lbl = tk.Label(row, text=entry.name,
                                font=("Microsoft YaHei", 9),
                                bg="#2a2a3e", fg="#cdd6f4", anchor="w")
            name_lbl.pack(side=tk.LEFT, padx=S(4))
            name_lbl.bind("<Button-1>", lambda e, idx=i: self._dm_toggle(idx))

            type_lbl = tk.Label(row, text="内置" if entry.is_builtin else "外部",
                                font=("Microsoft YaHei", 8),
                                bg="#2a2a3e", fg="#89b4fa" if entry.is_builtin else "#a6e3a1",
                                width=4)
            type_lbl.pack(side=tk.LEFT, padx=S(4))

            count_lbl = tk.Label(row, text=f"{entry.word_count} 条",
                                 font=("Consolas", 8),
                                 bg="#2a2a3e", fg="#f9e2af")
            count_lbl.pack(side=tk.RIGHT, padx=S(8))

            path_text = entry.path or "内置嵌入"
            path_lbl = tk.Label(row, text=path_text,
                                font=("Consolas", 8),
                                bg="#2a2a3e", fg="#6c7086", anchor="w")
            path_lbl.pack(side=tk.LEFT, fill=tk.X, expand=True, padx=S(8))

            # 更新该行的引用，并应用当前勾选状态
            self._dm_vars[i] = (entry, var, check_label)
            self._dm_refresh_row(i)

    def _dm_refresh_row(self, idx: int):
        """刷新指定行的复选框显示。"""
        entry, var, check_label = self._dm_vars[idx]
        if var.get():
            check_label.config(text="☑", fg="#a6e3a1")
        else:
            check_label.config(text="☐", fg="#6c7086")

    def _dm_toggle(self, idx: int):
        """切换某行的勾选状态。"""
        entry, var, _ = self._dm_vars[idx]
        var.set(not var.get())
        self._dm_refresh_row(idx)
        self._dm_update_info()

    def _dm_update_info(self):
        """更新管理窗口底部的统计信息以及复制按钮状态。"""
        total = len(self._dm_vars)
        selected = sum(1 for _, var, _ in self._dm_vars if var.get())
        self._dm_info.config(text=f"共 {total} 个字典，已选 {selected} 个")
        if selected > 0:
            self._dm_copy_btn.config(state=tk.NORMAL)
        else:
            self._dm_copy_btn.config(state=tk.DISABLED)

    def _dm_add_external(self):
        """添加外部字典文件到管理列表。"""
        paths = filedialog.askopenfilenames(
            title="选择一个或多个字典文件（.txt，每行一个密码）",
            filetypes=[("文本字典", "*.txt"), ("所有文件", "*.*")],
            initialdir=self.cfg.get("last_dir", ""))
        if not paths:
            return
        existing_paths = {e.path for e, _, _ in self._dm_vars if not e.is_builtin}
        added = 0
        for path in paths:
            if not os.path.isfile(path):
                continue
            abs_path = os.path.abspath(path)
            if abs_path in existing_paths:
                continue
            entry = DictEntry(Path(path).stem, abs_path, is_builtin=False)
            entry.load()
            if entry.word_count == 0:
                continue
            var = tk.BooleanVar(value=True)
            self._dm_vars.append((entry, var, None))
            existing_paths.add(abs_path)
            added += 1
        self.cfg["last_dir"] = os.path.dirname(paths[0])
        save_config(self.cfg)
        self._dm_render()
        self._dm_update_info()
        if added > 0:
            messagebox.showinfo("添加完成", f"成功添加 {added} 个字典。")
        else:
            messagebox.showwarning("提示", "没有添加新的字典（可能已存在或为空）。")

    def _dm_remove_selected(self):
        """移除选中的外部字典（内置字典不可移除）。"""
        removed = []
        keep = []
        for entry, var, _ in self._dm_vars:
            if var.get() and not entry.is_builtin:
                removed.append(entry)
            else:
                keep.append((entry, var, None))
        if not removed:
            messagebox.showinfo("提示", "请先勾选要移除的外部字典。\n（内置字典不能移除）")
            return
        self._dm_vars = keep
        self._dm_library = [entry for entry, _, _ in keep]
        self._dm_render()
        self._dm_update_info()
        messagebox.showinfo("移除完成", f"已移除 {len(removed)} 个字典。")

    def _dm_copy_selected(self):
        """复制所有选中的字典内容到剪贴板。"""
        if not self._dm_vars:
            return
        parts = []
        total_words = 0
        for entry, var, _ in self._dm_vars:
            if var.get():
                entry.load()
                text = "\n".join(w.decode("utf-8", "replace") for w in entry.words)
                parts.append(f"# ===== 字典: {entry.name} ({entry.word_count} 条) =====\n{text}")
                total_words += entry.word_count
        if not parts:
            messagebox.showinfo("提示", "请先勾选要复制的字典。")
            return
        text = "\n\n".join(parts)
        root = self._dm_win if self._dm_win else self.master
        if copy_to_clipboard(root, text):
            messagebox.showinfo("复制成功", f"已复制 {len(parts)} 个字典 共 {total_words} 条密码到剪贴板。")
        else:
            messagebox.showerror("复制失败", "无法复制到剪贴板，请手动选择后复制。")

    def _dm_select_all(self, select: bool):
        for i, (entry, var, _) in enumerate(self._dm_vars):
            var.set(select)
            self._dm_refresh_row(i)
        self._dm_update_info()

    def _dm_save(self, win):
        """保存字典库配置并关闭管理窗口。"""
        selected_indices = []
        for i, (entry, var, _) in enumerate(self._dm_vars):
            if var.get():
                selected_indices.append(i)
        if not selected_indices:
            messagebox.showwarning("提示", "请至少选择一个字典用于破解。")
            return

        self.dict_library = [entry for entry, _, _ in self._dm_vars]
        self.active_dicts = [i for i, (entry, var, _) in enumerate(self._dm_vars) if var.get()]

        # 保存配置
        cfg = self.cfg
        cfg["dict_library"] = [
            {"name": e.name, "path": e.path} for e in self.dict_library if not e.is_builtin
        ]
        cfg["active_dicts"] = [self.dict_library[i].name for i in self.active_dicts]
        save_config(cfg)
        self.cfg = cfg

        self._update_dict_label()
        self.lbl_status.config(text=f"字典配置已更新，当前启用 {len(self.active_dicts)} 个字典")
        win.destroy()

    # ---------------- 压缩包 ---------------- #
    def select_archive(self):
        path = filedialog.askopenfilename(
            title="选择要恢复密码的加密压缩包",
            filetypes=[("压缩包", "*.zip *.7z *.rar *.lz4"),
                       ("ZIP", "*.zip"), ("7z", "*.7z"),
                       ("RAR", "*.rar"), ("LZ4", "*.lz4"),
                       ("所有文件", "*.*")],
            initialdir=self.cfg.get("last_dir", ""))
        if path and os.path.isfile(path):
            self.entry_archive.delete(0, tk.END)
            self.entry_archive.insert(0, path)
            self.cfg["last_dir"] = os.path.dirname(path)
            save_config(self.cfg)
            self.lbl_status.config(text=f"已选择压缩包：{path}")
    def _on_shuffle_toggle(self):
        """勾选乱序撞库且未填种子时，自动生成随机种子填入输入框。"""
        if self.var_shuffle.get():
            if not self.entry_seed.get().strip():
                seed = random.randrange(1 << 32)
                self.entry_seed.delete(0, tk.END)
                self.entry_seed.insert(0, str(seed))
    # ==================== 断点续破相关方法 ======================= #
    def _get_active_dict_info(self) -> list:
        """获取当前选中字典的信息，用于断点匹配。"""
        info = []
        for idx in self.active_dicts:
            entry = self.dict_library[idx]
            info.append({
                "name": entry.name,
                "is_builtin": entry.is_builtin,
                "path": os.path.abspath(entry.path) if entry.path else None,
            })
        return info

    def _build_breakpoint_data(self) -> dict:
        """构建断点数据。"""
        return {
            "archive_path": os.path.abspath(self.archive),
            "archive_mtime": os.path.getmtime(self.archive) if os.path.exists(self.archive) else None,
            "dict_entries": self._get_active_dict_info(),
            "shuffle": self.var_shuffle.get(),
            "seed": self._shuffle_seed,
            "start_index": self._progress_count,
            "total_words": len(self._work_words) if self._work_words else 0,
            "timestamp": time.strftime("%Y-%m-%d %H:%M:%S"),
        }

    def _save_breakpoint(self):
        """保存当前进度到断点文件。"""
        if not self.archive or not os.path.exists(self.archive):
            return
        if not self._work_words:
            return

        # 从 shared 中读取最新进度
        counter = self.shared.get("counter")
        if counter is not None:
            try:
                n = counter[0] if isinstance(counter, list) else counter.value
            except Exception:
                n = self._progress_count
            self._progress_count = min(n, len(self._work_words))

        try:
            data = self._build_breakpoint_data()
            save_breakpoint(data)
        except Exception:
            pass

    def _clear_breakpoint(self):
        """清除断点文件。"""
        try:
            clear_breakpoint()
        except Exception:
            pass

    def _same_dict_entries(self, e1: list, e2: list) -> bool:
        """比较两个字典组合是否相同（路径完全一致）。"""
        if len(e1) != len(e2):
            return False
        for a, b in zip(e1, e2):
            if a["is_builtin"] != b["is_builtin"]:
                return False
            if a["path"] != b["path"]:
                return False
        return True

    def _match_breakpoint(self, bp: dict) -> bool:
        """检查断点是否与当前设置匹配。"""
        if not bp:
            return False

        # 压缩包路径
        if os.path.abspath(self.archive) != os.path.abspath(bp.get("archive_path", "")):
            return False

        # 压缩包修改时间
        try:
            current_mtime = os.path.getmtime(self.archive)
            if bp.get("archive_mtime") and abs(current_mtime - bp["archive_mtime"]) > 1e-6:
                return False
        except Exception:
            return False

        # 字典组合
        current_dicts = self._get_active_dict_info()
        if not self._same_dict_entries(current_dicts, bp.get("dict_entries", [])):
            return False

        # 乱序设置
        shuffle = self.var_shuffle.get()
        if shuffle != bp.get("shuffle", False):
            return False
        if shuffle:
            # 如果用户输入了种子，则必须与断点一致；否则使用断点种子
            seed_txt = self.entry_seed.get().strip()
            user_seed = int(seed_txt) if seed_txt.isdigit() else None
            if user_seed is not None and user_seed != bp.get("seed"):
                return False

        # 总字数一致
        if len(self._work_words) != bp.get("total_words", 0):
            return False

        return True

    def _on_close(self):
        if self.running:
            self.stop_flag.set()
            self._save_breakpoint()
            self.btn_stop.config(state=tk.DISABLED)
            self.lbl_status.config(text="正在停止并保存进度...")
            # 等待 worker 线程结束（最多 5 秒）
            if self.worker_thread:
                self.worker_thread.join(timeout=5)
        self.master.destroy()

    # ---------------- 破解流程 ---------------- #
    def start_crack(self):
        if self.running:
            return
        self.archive = self.entry_archive.get().strip().strip('"')
        if not self.archive:
            messagebox.showwarning("提示", "请先选择或输入要破解的压缩包路径。")
            return
        if not os.path.isfile(self.archive):
            messagebox.showwarning("提示", "压缩包路径无效，请检查。")
            return
        if not self.active_dicts:
            messagebox.showwarning("提示", "请先在字典管理中勾选要使用的字典。")
            return

        # 构建组合字典（原始顺序，暂不打乱）
        self._work_words = []
        for idx in self.active_dicts:
            entry = self.dict_library[idx]
            entry.load()
            self._work_words.extend(entry.words)
        if not self._work_words:
            messagebox.showwarning("提示", "所选字典均为空。")
            return
        # 如果乱序已启用但种子为空，自动生成一个种子（确保输入框有值）
        if self.var_shuffle.get() and not self.entry_seed.get().strip():
            seed = random.randrange(1 << 32)
            self.entry_seed.delete(0, tk.END)
            self.entry_seed.insert(0, str(seed))

        total = len(self._work_words)
        shuffle_enabled = self.var_shuffle.get()
        seed_txt = self.entry_seed.get().strip()
        user_seed = int(seed_txt) if seed_txt.isdigit() else None

        # ---------- 断点检测 ----------
        self._resume_from = 0
        resume = False
        bp = load_breakpoint()
        if bp:
            if self._match_breakpoint(bp):
                if messagebox.askyesno(
                        "断点续破",
                        f"检测到上次破解进度\n\n"
                        f"压缩包：{os.path.basename(bp.get('archive_path', ''))}\n"
                        f"字典组合：{'、'.join([e['name'] for e in bp.get('dict_entries', [])])}\n"
                        f"已尝试：{bp.get('start_index', 0)} / {bp.get('total_words', 0)}\n\n"
                        f"是否从断点继续？"):
                    resume = True
                    self._resume_from = bp.get("start_index", 0)
                else:
                    clear_breakpoint()
                    self.lbl_status.config(text="已清除断点，将从头开始。")
            else:
                clear_breakpoint()
                self.lbl_status.config(text="断点信息不匹配，已清除。")

        # ---------- 乱序处理（根据断点决定种子）----------
        if shuffle_enabled:
            if resume:
                # 从断点继续：强制使用断点的种子，保证顺序一致
                seed = bp.get("seed") if bp.get("seed") is not None else (
                    user_seed if user_seed is not None else random.randrange(1 << 32)
                )
            else:
                seed = user_seed if user_seed is not None else random.randrange(1 << 32)
            self._shuffle_seed = seed
            random.Random(seed).shuffle(self._work_words)
        else:
            self._shuffle_seed = None

        # 进度条初始化
        self.running = True
        self.stop_flag.clear()
        self.btn_start.config(state=tk.DISABLED)
        self.btn_stop.config(state=tk.NORMAL)
        self.progress.config(maximum=total, value=self._resume_from)
        self.lbl_pct.config(text=f"{self._resume_from / total * 100:.2f}%")
        self.lbl_status.config(
            text=("正在续破..." if resume else "正在开始...") + f" 共 {total} 条")
        self.lbl_current.config(text="当前尝试：-")
        self.lbl_dict_info.config(text="当前字典：准备中...")
        self.lbl_speed.config(text="速度：0 次/秒")
        self.lbl_eta.config(text="预计剩余：--")

        self._last_check_time = time.time()
        self._last_check_count = self._resume_from
        self._progress_count = self._resume_from
        self._speed = 0.0
        self._eta = "--"
        self._crack_start_time = time.time()
        self._eta_smoother = ETASmoother(window_seconds=3.0)   # 每次开始都重置，避免上次残留数据干扰

        self.worker_thread = threading.Thread(target=self._run_crack, daemon=True)
        self.worker_thread.start()
        self.master.after(100, self._update_progress)

    def _run_crack(self):
        ext = os.path.splitext(self.archive)[1].lower()
        start_index = self._resume_from
        total = len(self._work_words)
        self._temp_dict_file = None
        try:
            if ext == ".zip":
                if is_aes_zip(self.archive):
                    sevenzip = find_7z()
                    if not sevenzip:
                        self.master.after(0, self._finish, ("no7z", None))
                        return
                    dict_path = self._ensure_temp_dict()
                    result = crack_7z_process(self.archive, dict_path,
                                              sevenzip, total,
                                              start_index, self.shared, self.stop_flag)
                else:
                    result = crack_zip_thread(self.archive, self._work_words,
                                              start_index, self.shared, self.stop_flag)
            elif ext in (".7z", ".rar", ".lz4", ".tar", ".xz", ".bz2",
                         ".gz", ".zst", ".arj", ".cab", ".iso"):
                sevenzip = find_7z()
                if not sevenzip:
                    self.master.after(0, self._finish, ("no7z", None))
                    return
                dict_path = self._ensure_temp_dict()
                result = crack_7z_process(self.archive, dict_path,
                                          sevenzip, total,
                                          start_index, self.shared, self.stop_flag)
            else:
                result = ("unsupported", None)
            self.master.after(0, self._finish, result)
        except Exception as e:
            self.master.after(0, self._finish, ("error", str(e).encode()))

    def _ensure_temp_dict(self) -> str:
        """把组合字典写入临时文件（供 7z 子进程读取）。"""
        if self._temp_dict_file and os.path.exists(self._temp_dict_file):
            return self._temp_dict_file
        fd, path = tempfile.mkstemp(suffix=".txt", prefix="combined_dict_")
        with os.fdopen(fd, "wb") as f:
            for w in self._work_words:
                f.write(w + b"\n")
        self._temp_dict_file = path
        return path

    def _cleanup_temp(self):
        if self._temp_dict_file and os.path.exists(self._temp_dict_file):
            try:
                os.unlink(self._temp_dict_file)
            except Exception:
                pass
        self._temp_dict_file = None

    def _get_dict_info_at(self, n: int) -> Tuple[Optional[DictEntry], int, int, int]:
        """根据全局进度值返回 (字典条目, 字典内进度, 字典位次, 字典总数)。"""
        remaining = n
        for pos, idx in enumerate(self.active_dicts):
            entry = self.dict_library[idx]
            sz = entry.word_count
            if remaining < sz:
                return entry, remaining, pos, len(self.active_dicts)
            remaining -= sz
        if self.active_dicts:
            idx = self.active_dicts[-1]
            entry = self.dict_library[idx]
            return entry, entry.word_count, len(self.active_dicts) - 1, len(self.active_dicts)
        return None, 0, 0, 0

    def _update_progress(self):
        if not self.running:
            return
        counter = self.shared.get("counter")
        found = self.shared.get("found")
        current = self.shared.get("current")
        total = len(self._work_words) if self._work_words else 1

        if counter is not None:
            try:
                n = counter[0] if isinstance(counter, list) else counter.value
            except Exception:
                n = 0
            n = min(n, total)
            self._progress_count = n   # 更新实际进度
            self.progress.config(value=n)
            self.lbl_pct.config(text=f"{n / total * 100:.2f}%")

            # 更新速度 / 预计剩余（速度显示不变，ETA 改用平滑器）
            now = time.time()
            elapsed = now - self._last_check_time
            if elapsed >= 0.5:
                speed = (n - self._last_check_count) / elapsed
                if speed >= 0:
                    self._speed = speed
                    self._last_check_time = now
                    self._last_check_count = n
                self.lbl_speed.config(text=f"速度：{self._speed:.0f} 次/秒")

                # —— 平滑 ETA ——
                ratio = n / total if total > 0 else 0
                eta_seconds = self._eta_smoother.add(ratio)
                if eta_seconds is not None:
                    self._eta = f"{int(eta_seconds)}秒"
                else:
                    self._eta = "--"
                self.lbl_eta.config(text=f"预计剩余：{self._eta}")

            # 更新当前字典信息
            entry, inner, pos, total_dicts = self._get_dict_info_at(n)
            if entry:
                self.lbl_dict_info.config(
                    text=f"当前字典：{entry.name}（{pos + 1}/{total_dicts}）  "
                         f"本字典进度：{inner}/{entry.word_count}  "
                         f"({(inner / entry.word_count * 100) if entry.word_count else 0:.1f}%)"
                )

        if current is not None:
            try:
                cur = current[0] if isinstance(current, list) else bytes(current[:60])
            except Exception:
                cur = b""
            try:
                s = cur.decode("utf-8", "replace")
            except Exception:
                s = str(cur)
            self.lbl_current.config(text="当前尝试：" + s)

        if found is not None:
            try:
                f = found[0] if isinstance(found, list) else bool(found.value)
            except Exception:
                f = False
            if f:
                self.lbl_status.config(text="✅ 已找到密码！正在整理结果...")

        self.master.after(100, self._update_progress)

    def _finish(self, result):
        self.running = False
        self.btn_start.config(state=tk.NORMAL)
        self.btn_stop.config(state=tk.DISABLED)
        self._cleanup_temp()

        self.lbl_speed.config(text="速度：0 次/秒")
        self.lbl_eta.config(text="预计剩余：--")

        status, pw = result

        # 构造历史记录
        history = load_history()
        entry_record = {
            "time": time.strftime("%Y-%m-%d %H:%M:%S"),
            "archive": os.path.basename(self.archive) if self.archive else "",
            "archive_path": self.archive,
            "dicts": [self.dict_library[idx].name for idx in self.active_dicts],
            "result": status,
            "password": "",
            "duration": round(time.time() - self._crack_start_time, 2),
            "speed": round(self._speed, 1),
            "total_words": len(self._work_words) if self._work_words else 0,
            "seed": self._shuffle_seed,          # 新增
        }

        if status == "found":
            try:
                show = pw.decode("utf-8", "replace")
            except Exception:
                show = str(pw)
            entry_record["password"] = show
            self.lbl_status.config(text=f"✅ 找到密码：{show}")
            if copy_to_clipboard(self.master, show):
                messagebox.showinfo("破解成功", f"密码：{show}\n\n已自动复制到剪贴板。")
            else:
                messagebox.showinfo("破解成功", f"密码：{show}")
            self.progress.config(value=self.progress["maximum"])
            self.lbl_pct.config(text="100.00%")
            self._clear_breakpoint()
        elif status == "stopped":
            self.lbl_status.config(text="⏹ 已停止，断点已保存。")
            entry_record["result"] = "stopped"
            self._save_breakpoint()      # 停止时确保断点保存
        elif status == "fail":
            self.lbl_status.config(text="❌ 字典已全部尝试，未找到密码。")
            messagebox.showwarning("未找到", "字典已全部尝试完毕，未找到密码。")
            self._clear_breakpoint()
        elif status == "noenc":
            self.lbl_status.config(text="⚠️ 该压缩包未加密。")
            messagebox.showinfo("提示", "该压缩包内容未加密，无需恢复密码。")
            self._clear_breakpoint()
        elif status == "no7z":
            self.lbl_status.config(text="❌ 未找到 7z.exe。")
            messagebox.showerror("缺少依赖", "处理该格式需要 7-Zip。\n请安装：https://www.7-zip.org/")
        elif status == "unsupported":
            self.lbl_status.config(text="❌ 不支持的文件类型。")
            messagebox.showerror("错误", "不支持该文件类型。")
            self._clear_breakpoint()
        elif status == "error":
            msg = pw.decode("utf-8", "replace") if isinstance(pw, bytes) else str(pw)
            entry_record["error"] = msg
            self.lbl_status.config(text="❌ 发生错误。")
            messagebox.showerror("错误", msg)
            self._clear_breakpoint()
        else:
            self.lbl_status.config(text="已停止。")
            entry_record["result"] = "stopped"

        # 保存历史（最多保留100条）
        history.insert(0, entry_record)
        history = history[:100]
        save_history(history)

    def stop_crack(self):
        if self.running:
            self.stop_flag.set()               # 立即通知线程/进程停止
            self._save_breakpoint()            # 保存断点
            self.btn_stop.config(state=tk.DISABLED)
            self.lbl_status.config(text="正在停止，断点已保存...")

    # ---------------- 历史记录（重做版）---------------- #
    def open_history(self):
        """打开历史记录窗口（深色主题 + 详情面板 + 可勾选删除）。"""
        win = tk.Toplevel(self.master)
        win.title("🕘 历史记录")
        win.geometry(f"{S(880)}x{S(760)}")          # 调高，避免底部按钮被遮挡
        win.minsize(S(880), S(700))
        win.configure(bg="#1e1e2e")
        win.transient(self.master)

        history = load_history()
        if not history:
            frame = tk.Frame(win, bg="#1e1e2e")
            frame.pack(expand=True)
            tk.Label(frame, text="🕘", font=("Segoe UI Symbol", 56),
                     bg="#1e1e2e", fg="#313244").pack()
            tk.Label(frame, text="暂无历史记录", font=("Microsoft YaHei", 15, "bold"),
                     bg="#1e1e2e", fg="#a6adc8").pack(pady=S(12))
            tk.Label(frame, text="完成一次破解后会自动记录在这里",
                     font=("Microsoft YaHei", 10),
                     bg="#1e1e2e", fg="#585b70").pack()
            return

        # 顶部标题 + 统计
        header = tk.Frame(win, bg="#1e1e2e")
        header.pack(fill=tk.X, padx=S(16), pady=(S(14), S(6)))
        tk.Label(header, text="🕘 历史记录", font=("Microsoft YaHei", 16, "bold"),
                 bg="#1e1e2e", fg="#89b4fa").pack(side=tk.LEFT)
        stats = tk.Label(header,
                         text=f"共 {len(history)} 条  ·  成功 {sum(1 for h in history if h.get('result') == 'found')} 条",
                         font=("Microsoft YaHei", 10),
                         bg="#1e1e2e", fg="#a6adc8")
        stats.pack(side=tk.RIGHT, pady=(S(6), 0))

        # 表格（深色主题）
        body = tk.Frame(win, bg="#181825")
        body.pack(fill=tk.BOTH, expand=True, padx=S(16), pady=S(4))

        style = ttk.Style(win)
        try:
            style.theme_use("clam")
        except Exception:
            pass
        style.configure("Hist.Treeview",
                        background="#181825", fieldbackground="#181825",
                        foreground="#cdd6f4", rowheight=S(30), borderwidth=0,
                        font=("Microsoft YaHei", 9))
        style.map("Hist.Treeview",
                  background=[("selected", "#45475a")],
                  foreground=[("selected", "#ffffff")])
        style.configure("Hist.Treeview.Heading",
                        background="#2a2a3e", foreground="#89b4fa",
                        relief="flat", font=("Microsoft YaHei", 9, "bold"))
        style.map("Hist.Treeview.Heading",
                  background=[("active", "#313244")])

        # 多一个“选择”列
        columns = ("选择", "时间", "压缩包", "字典", "结果", "密码", "耗时", "速度")
        tree = ttk.Treeview(body, columns=columns, show="headings",
                            style="Hist.Treeview")
        vsb = ttk.Scrollbar(body, orient="vertical", command=tree.yview)
        hsb = ttk.Scrollbar(body, orient="horizontal", command=tree.xview)
        tree.configure(yscrollcommand=vsb.set, xscrollcommand=hsb.set)

        widths = (60, 140, 200, 170, 90, 130, 80, 90)
        for col, w in zip(columns, widths):
            tree.heading(col, text=col)
            if col == "选择":
                tree.column(col, width=S(w), anchor="center", minwidth=S(50))
            else:
                tree.column(col, width=S(w), anchor="w", minwidth=S(60))

        tree.tag_configure("odd", background="#181825")
        tree.tag_configure("even", background="#1e1e2e")
        tree.tag_configure("found", foreground="#a6e3a1")
        tree.tag_configure("fail", foreground="#f38ba8")
        tree.tag_configure("stopped", foreground="#fab387")
        tree.tag_configure("error", foreground="#f38ba8")
        tree.tag_configure("noenc", foreground="#f9e2af")
        tree.tag_configure("unsupported", foreground="#9399b2")

        # 存储每行的勾选状态
        tree._checked = {}

        for idx, h in enumerate(history):
            row_tag = "odd" if idx % 2 == 0 else "even"
            result = h.get("result", "")
            color_tag = result if result in RESULT_LABELS else "even"
            item_id = tree.insert("", "end", iid=str(idx), values=(
                "☐",
                h.get("time", ""),
                h.get("archive", ""),
                "、".join(h.get("dicts", [])),
                RESULT_LABELS.get(result, result),
                h.get("password", ""),
                f"{h.get('duration', 0)}s",
                f"{h.get('speed', 0)}/s",
            ), tags=(row_tag, color_tag))
            tree._checked[item_id] = False

        tree.grid(row=0, column=0, sticky="nsew")
        vsb.grid(row=0, column=1, sticky="ns")
        hsb.grid(row=1, column=0, sticky="ew")
        body.grid_rowconfigure(0, weight=1)
        body.grid_columnconfigure(0, weight=1)

        # 点击第一列切换勾选状态
        def on_history_click(event):
            if tree.identify_region(event.x, event.y) != "cell":
                return
            if tree.identify_column(event.x) != "#1":
                return
            item = tree.identify_row(event.y)
            if not item:
                return
            checked = tree._checked.get(item, False)
            tree._checked[item] = not checked
            tree.set(item, "选择", "☑" if not checked else "☐")

        tree.bind("<Button-1>", on_history_click)

        # 详情面板
        detail = tk.Frame(win, bg="#1e1e2e")
        detail.pack(fill=tk.X, padx=S(16), pady=S(8))
        tk.Label(detail, text="📄 记录详情（点击上方任意一行查看）",
                 font=("Microsoft YaHei", 9, "bold"),
                 bg="#1e1e2e", fg="#a6adc8").pack(anchor="w")
        self._history_detail = tk.Text(detail, height=S(8), font=("Consolas", 9),
                                       bg="#11111b", fg="#cdd6f4",
                                       insertbackground="#cdd6f4",
                                       relief="flat", wrap="word")
        self._history_detail.pack(fill=tk.X, pady=(S(4), 0))
        self._history_detail.config(state=tk.DISABLED)

        tree.bind("<<TreeviewSelect>>",
                  lambda e: self._show_history_detail(tree, history))

        # 底部按钮
        bottom = tk.Frame(win, bg="#1e1e2e")
        bottom.pack(fill=tk.X, padx=S(16), pady=S(10))

        # 删除选中按钮（内部函数方便访问 tree/history/win）
        def delete_selected():
            checked_items = [item for item, checked in tree._checked.items() if checked]
            if not checked_items:
                messagebox.showinfo("提示", "请先勾选要删除的记录。", parent=win)
                return
            if not messagebox.askyesno("确认", f"确定删除选中的 {len(checked_items)} 条记录吗？", parent=win):
                return
            # 从大到小删除原始索引
            indices = sorted([int(item) for item in checked_items], reverse=True)
            for idx in indices:
                if 0 <= idx < len(history):
                    del history[idx]
            save_history(history)
            # 刷新表格
            tree.delete(*tree.get_children())
            tree._checked.clear()
            for new_idx, h in enumerate(history):
                row_tag = "odd" if new_idx % 2 == 0 else "even"
                result = h.get("result", "")
                color_tag = result if result in RESULT_LABELS else "even"
                item_id = tree.insert("", "end", iid=str(new_idx), values=(
                    "☐",
                    h.get("time", ""),
                    h.get("archive", ""),
                    "、".join(h.get("dicts", [])),
                    RESULT_LABELS.get(result, result),
                    h.get("password", ""),
                    f"{h.get('duration', 0)}s",
                    f"{h.get('speed', 0)}/s",
                ), tags=(row_tag, color_tag))
                tree._checked[item_id] = False
            # 更新统计
            stats.config(text=f"共 {len(history)} 条  ·  成功 {sum(1 for h in history if h.get('result') == 'found')} 条")
            messagebox.showinfo("完成", f"已删除 {len(checked_items)} 条记录。", parent=win)

        tk.Button(bottom, text="🗑️ 清空历史",
                  command=lambda: self._clear_history(win),
                  font=("Microsoft YaHei", 9), bg="#f38ba8", fg="#11111b",
                  relief="flat", cursor="hand2").pack(side=tk.RIGHT)
        tk.Button(bottom, text="❌ 删除选中",
                  command=delete_selected,
                  font=("Microsoft YaHei", 9), bg="#fab387", fg="#11111b",
                  relief="flat", cursor="hand2").pack(side=tk.RIGHT, padx=S(5))

    def _show_history_detail(self, tree, history):
        """在详情面板显示选中记录的信息。"""
        sel = tree.selection()
        if not sel:
            return
        index = tree.index(sel[0])
        if index < 0 or index >= len(history):
            return
        h = history[index]
        lines = []
        lines.append(f"时间：{h.get('time', '')}")
        lines.append(f"压缩包：{h.get('archive_path', h.get('archive', ''))}")
        lines.append(f"使用字典：{'、'.join(h.get('dicts', []))}")
        lines.append(f"结果：{RESULT_LABELS.get(h.get('result', ''), h.get('result', ''))}")
        if h.get("seed") is not None:
            lines.append(f"乱序种子：{h.get('seed')}")
        if h.get("password"):
            lines.append(f"密码：{h['password']}")
        lines.append(f"耗时：{h.get('duration', 0)} 秒"
                     f"    速度：{h.get('speed', 0)} 次/秒"
                     f"    字典总条数：{h.get('total_words', 0)}")
        if h.get("error"):
            lines.append(f"错误信息：{h['error']}")
        self._history_detail.config(state=tk.NORMAL)
        self._history_detail.delete("1.0", tk.END)
        self._history_detail.insert("1.0", "\n".join(lines))
        self._history_detail.config(state=tk.DISABLED)

    def _clear_history(self, win):
        """清空历史记录。"""
        if messagebox.askyesno("确认", "确定要清空所有历史记录吗？"):
            save_history([])
            win.destroy()
            messagebox.showinfo("完成", "历史记录已清空。")

